(2024, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Un traitement de fond de la Polyarthrite Rhumatoïde peut être :', '[{"l":"A","t":"Un Anti-TNFα","c":true},{"l":"B","t":"La Méthylprednisolone","c":false},{"l":"C","t":"Le Méthotrexate","c":true},{"l":"D","t":"Le Diclofénac","c":false},{"l":"E","t":"Le Leflunomide","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2025, 10, 'Rhumatologie', 'Rhumatologie', NULL, false, true, 'Le diagnostic de l''ostéoporose doit être évoqué devant :', '[{"l":"A","t":"Une diminution de la taille","c":true},{"l":"B","t":"Des douleurs osseuses diffuses en l''absence de fracture","c":false},{"l":"C","t":"Une fracture survenant après un traumatisme à bas niveau d''énergie","c":true},{"l":"D","t":"Une condensation osseuse à la radiographie","c":false},{"l":"E","t":"Une densitométrie osseuse basse","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2026, 10, 'Rhumatologie', 'Rhumatologie', NULL, false, true, 'Parmi les facteurs de risque de l''ostéoporose :', '[{"l":"A","t":"La ménopause tardive","c":false},{"l":"B","t":"La ménopause précoce","c":true},{"l":"C","t":"L''apport suffisant en calcium et en Vitamine D","c":false},{"l":"D","t":"Le surpoids","c":false},{"l":"E","t":"La corticothérapie prolongée","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2027, 10, 'Rhumatologie', 'Rhumatologie', NULL, false, true, 'À propos de l''ostéomalacie :', '[{"l":"A","t":"C''est une ostéopathie raréfiante maligne","c":false},{"l":"B","t":"C''est une ostéopathie raréfiante bénigne","c":true},{"l":"C","t":"La carence en vitamine D est la cause la plus fréquente","c":true},{"l":"D","t":"Les myalgies sont peu fréquentes","c":false},{"l":"E","t":"Les douleurs osseuses sont le plus souvent diffuses et symétriques","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2028, 6, 'Rhumatologie', 'Rhumatologie', NULL, false, true, 'Dans la gonarthrose, la lésion initiale siège au niveau de :', '[{"l":"A","t":"Ligaments croisés","c":false},{"l":"B","t":"Ménisques","c":false},{"l":"C","t":"Bourse séreuse","c":false},{"l":"D","t":"Cartilage articulaire","c":true},{"l":"E","t":"Os sous chondral","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2029, 17, 'Rhumatologie', 'Maladies luxantes de la hanche', NULL, false, true, 'Au cours de la coxarthrose, la radiographie standard peut retrouver :', '[{"l":"A","t":"Fracture déplacée","c":false},{"l":"B","t":"Pincement de l''interligne articulaire","c":true},{"l":"C","t":"Luxation congénitale","c":false},{"l":"D","t":"Ostéophytes","c":true},{"l":"E","t":"Géodes osseuses","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2030, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant l''accès aigu goutteux :', '[{"l":"A","t":"Débute souvent de façon brutale","c":true},{"l":"B","t":"Est habituellement bilatéral d''emblée","c":false},{"l":"C","t":"L''atteinte du gros orteil est la plus fréquente","c":true},{"l":"D","t":"S''accompagne de signes inflammatoires locaux intenses","c":true},{"l":"E","t":"Survient préférentiellement la nuit","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2031, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Concernant la lombosciatique commune :', '[{"l":"A","t":"Le conflit disco-radiculaire est la cause la plus fréquente","c":true},{"l":"B","t":"Le trajet est souvent monoradiculaire de topographie sciatique L3 ou L4","c":false},{"l":"C","t":"Une impulsivité à la toux peut se voir","c":true},{"l":"D","t":"Le signe de Lasègue est toujours positif","c":false},{"l":"E","t":"Les examens complémentaires sont demandés d''emblée","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2032, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'Au cours de la spondylodiscite tuberculeuse :', '[{"l":"A","t":"Le début est souvent insidieux","c":true},{"l":"B","t":"Le début est souvent brutal","c":false},{"l":"C","t":"L''atteinte du rachis thoracique est fréquente","c":true},{"l":"D","t":"Les signes généraux sont constants","c":false},{"l":"E","t":"Des complications neurologiques sont possibles","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2033, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'À propos de la spondylodiscite tuberculeuse :', '[{"l":"A","t":"La radiographie standard peut être normale au début","c":true},{"l":"B","t":"L''IRM du rachis est l''examen de choix","c":true},{"l":"C","t":"La TDM du rachis est l''examen de choix","c":false},{"l":"D","t":"La mise en évidence de BK sur les prélèvements permet le diagnostic de certitude","c":true},{"l":"E","t":"La présence isolée d''un granulome tuberculoïde sur les prélèvements tissulaires permet le diagnostic de certitude","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2034, 20, 'Rhumatologie', 'Rhumatologie', NULL, false, true, 'La tendinopathie non rompue du supra-épineux se caractérise par :', '[{"l":"A","t":"Un tableau clinique d''une épaule pseudo paralytique","c":false},{"l":"B","t":"La mobilité passive est toujours limitée","c":false},{"l":"C","t":"La manœuvre de Jobe est douloureuse","c":true},{"l":"D","t":"La manœuvre de Jobe est déficitaire et indolore","c":false},{"l":"E","t":"La manœuvre de patte est douloureuse","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2035, 5, 'Rhumatologie', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Une algodystrophie peut être précédée par :', '[{"l":"A","t":"Une infection ostéoarticulaire","c":false},{"l":"B","t":"Une chirurgie orthopédique","c":true},{"l":"C","t":"Un phénomène de Raynaud","c":false},{"l":"D","t":"Un accident vasculaire cérébral","c":true},{"l":"E","t":"Une entorse","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2036, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Une algodystrophie peut se manifester par :', '[{"l":"A","t":"Œdème","c":true},{"l":"B","t":"Troubles de la sudation","c":true},{"l":"C","t":"Déformations articulaires précoces irréversibles","c":false},{"l":"D","t":"Modification de la coloration cutanée","c":true},{"l":"E","t":"Troubles trophiques cutanés et unguéaux","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2037, 35, 'Rhumatologie', 'Syndrome du canal carpien', NULL, false, true, 'À propos du syndrome du canal carpien :', '[{"l":"A","t":"C''est la compression du nerf ulnaire dans le canal carpien","c":false},{"l":"B","t":"C''est la compression du nerf radial dans le canal carpien","c":false},{"l":"C","t":"C''est la compression du nerf médian dans le canal carpien","c":true},{"l":"D","t":"Il touche plus fréquemment l''homme","c":false},{"l":"E","t":"Il est le plus souvent idiopathique","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2038, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Traumatisme par un mécanisme des « tableaux de bord » peut entraîner :', '[{"l":"A","t":"Une luxation antérieure de la hanche","c":false},{"l":"B","t":"Une fracture du poignet","c":false},{"l":"C","t":"Une fracture de la rotule","c":true},{"l":"D","t":"Une fracture-luxation postérieure de la hanche","c":true},{"l":"E","t":"Une lésion ligamentaire du genou","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2020-2021"]'::jsonb),
(2039, 26, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'L''attitude vicieuse caractéristique de la luxation postérieure de la hanche est :', '[{"l":"A","t":"Adduction, rotation interne, raccourcissement et flexion du membre","c":true},{"l":"B","t":"Abduction, allongement, rotation externe du membre","c":false},{"l":"C","t":"Abduction, rotation interne, extension du membre","c":false},{"l":"D","t":"Abduction, rotation externe, raccourcissement, extension du membre","c":false},{"l":"E","t":"Flexion, raccourcissement du membre","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2020-2021"]'::jsonb),
(2040, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Les lésions les plus probables qui peuvent s''associer à une luxation postérieure de la hanche :', '[{"l":"A","t":"Fracture de la tête fémorale","c":true},{"l":"B","t":"Lésion du nerf fémoral","c":false},{"l":"C","t":"Fracture de la paroi postérieure du cotyle","c":true},{"l":"D","t":"Lésion du nerf radial","c":false},{"l":"E","t":"Lésion du nerf sciatique","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2020-2021"]'::jsonb),
(2041, 32, 'Traumatologie', 'Traumatologie générale', NULL, false, true, 'Parmi ces propositions cochez celles relatives aux complications d''une fracture de la diaphyse humérale :', '[{"l":"A","t":"Ouverture cutanée","c":true},{"l":"B","t":"Lésion du nerf ulnaire","c":false},{"l":"C","t":"Lésion de l''artère fémorale","c":false},{"l":"D","t":"Pseudarthrose","c":true},{"l":"E","t":"Raideur du coude","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2020-2021"]'::jsonb),
(2042, 18, 'Traumatologie', 'Amputations des membres', NULL, false, true, 'Une paralysie motrice du nerf radial se manifeste par :', '[{"l":"A","t":"Impossibilité de faire l''extension du poignet et de la main et impossibilité à faire l''abduction du pouce","c":true},{"l":"B","t":"Impossibilité à faire l''abduction de l''épaule","c":false},{"l":"C","t":"Impossibilité à faire la flexion dorsale du pied","c":false},{"l":"D","t":"Impossibilité de faire la flexion du poignet et de la main et impossibilité à faire l''adduction du pouce","c":false},{"l":"E","t":"Anesthésie du moignon de l''épaule","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2020-2021"]'::jsonb),
(2043, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Les fractures de la rotule : (cochez les réponses justes)', '[{"l":"A","t":"S''accompagnent toujours d''une rupture de l''appareil extenseur","c":false},{"l":"B","t":"Sont des fractures assez fréquentes","c":true},{"l":"C","t":"Peuvent être traités orthopédiquement","c":true},{"l":"D","t":"S''accompagnent souvent de lésions cutanées","c":true},{"l":"E","t":"Le mécanisme direct est le plus fréquent","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2022-2023"]'::jsonb),
(2044, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', NULL, false, true, 'Dans les entorses du genou : (cochez les réponses justes)', '[{"l":"A","t":"L''hyperflexion du genou est responsable d''une lésion du LCA","c":false},{"l":"B","t":"L''atteinte du LLI est due à un mécanisme de varus forcé","c":false},{"l":"C","t":"L''atteinte du LLI est due à un mécanisme de valgus forcé","c":true},{"l":"D","t":"L''hyperextension dans le vide peut être responsable d''une lésion du LCP","c":true},{"l":"E","t":"L''hyperextension dans le vide peut être responsable d''une lésion du LCA","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2022-2023"]'::jsonb),
(2045, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'Concernant les luxations du coude, la forme anatomopathologique la plus fréquente est :', '[{"l":"A","t":"La luxation antérieure","c":false},{"l":"B","t":"La luxation postérieure pure","c":false},{"l":"C","t":"La luxation postéro-latérale","c":true},{"l":"D","t":"La luxation latérale","c":false},{"l":"E","t":"Luxation de l''olécrane isolée","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2022-2023"]'::jsonb),
(2046, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'La Médecine Physique et de Réadaptation :', '[{"l":"A","t":"Est une spécialité médicale visant l''amélioration du fonctionnement physique et cognitif","c":true},{"l":"B","t":"Son but est de traiter l''organe","c":false},{"l":"C","t":"Elle est définie par un objectif qui est la fonction","c":true},{"l":"D","t":"Il s''agit d''une spécialité qui n''est pas déterminée par une population spécifique ou un organe spécifique","c":true},{"l":"E","t":"C''est une spécialité qui prend en charge uniquement des adultes","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2047, 8, 'MPR', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'La rééducation des pathologies traumatiques permet :', '[{"l":"A","t":"De soulager une douleur, de récupérer l''amplitude nécessaire des articulations","c":true},{"l":"B","t":"La consolidation osseuse","c":false},{"l":"C","t":"De retrouver une bonne qualité d''équilibre et de coordination des gestes","c":true},{"l":"D","t":"La réduction orthopédique des fractures déplacées","c":false},{"l":"E","t":"De récupérer une force musculaire normale","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2048, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'Les techniques de base de la rééducation en traumatologie sont :', '[{"l":"A","t":"La masso-kinésithérapie","c":true},{"l":"B","t":"La physiothérapie","c":true},{"l":"C","t":"Ergothérapie","c":true},{"l":"D","t":"Ostéomyoplastie","c":false},{"l":"E","t":"Immobilisation plâtrée","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2049, 24, 'MPR', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Parmi les étiologies du handicap, un seul n''est pas correct, lequel ?', '[{"l":"A","t":"Les lésions cérébrales","c":false},{"l":"B","t":"Les lésions médullaires","c":false},{"l":"C","t":"Les rhumatismes inflammatoires","c":false},{"l":"D","t":"Les lésions du plexus brachial","c":false},{"l":"E","t":"Le syndrome grippal","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2050, 4, 'MPR', 'Situations d’handicap et concept de qualité de vie', NULL, false, true, 'Le Handicap :', '[{"l":"A","t":"Dans 80 % des cas, le handicap n''est pas visible au premier regard","c":true},{"l":"B","t":"Dans les pays en voie de développement, ce sont les pathologies infectieuses et infantiles qui sont les principales causes de handicap","c":true},{"l":"C","t":"Dans les pays développés, ce sont des pathologies dues au vieillissement, en particulier les pathologies cardio-neuro-vasculaires, qui sont le plus souvent à l''origine d''une situation de handicap","c":true},{"l":"D","t":"Dans les pays développés, ce sont les pathologies infectieuses et infantiles qui sont les principales causes de handicap","c":false},{"l":"E","t":"Dans les pays en voie de développement, ce sont des pathologies dues au vieillissement qui sont le plus souvent à l''origine d''une situation de handicap","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2051, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'L''amputation :', '[{"l":"A","t":"L''ostéomyoplastie est la technique chirurgicale de choix","c":true},{"l":"B","t":"Le nombre d''amputations de membre supérieur représenterait environ 10 à 15% des amputations de membres inférieurs","c":true},{"l":"C","t":"Les amputations des membres supérieurs sont plus fréquentes que les amputations des membres inférieurs","c":false},{"l":"D","t":"Les amputations de causes vasculaires touchent surtout les sujets jeunes, rarement les personnes âgées","c":false},{"l":"E","t":"Les amputations de causes tumorales sont consécutives à des tumeurs des os et des parties molles","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2052, 7, 'Traumatologie', 'Traumatologie générale', NULL, false, true, 'Quels sont les déplacements classiques du membre inférieur en cas de fracture de l''extrémité supérieure du fémur ?', '[{"l":"A","t":"Raccourcissement","c":true},{"l":"B","t":"Adduction","c":true},{"l":"C","t":"Abduction","c":false},{"l":"D","t":"Rotation interne","c":false},{"l":"E","t":"Allongement","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2053, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'Quel est le traitement de choix concernant un patient de 58 ans, sans ATCD et présentant une fracture cervicale vraie Garden 4 de col fémoral ?', '[{"l":"A","t":"Traitement orthopédique","c":false},{"l":"B","t":"Traitement chirurgical conservateur","c":true},{"l":"C","t":"Traitement fonctionnel","c":false},{"l":"D","t":"Traitement chirurgical radical","c":false},{"l":"E","t":"Arthroplastie totale de la hanche","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2054, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'Les fractures du massif trochantérien de l''extrémité supérieure du fémur sont plus exposées dans leur évolution que les fractures de col, au risque de :', '[{"l":"A","t":"Pseudarthrose","c":false},{"l":"B","t":"Nécrose aseptique de la tête fémorale","c":false},{"l":"C","t":"Complications de décubitus","c":false},{"l":"D","t":"Cal vicieux","c":true},{"l":"E","t":"Raideur de la hanche","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2055, 31, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'Quelles sont les possibilités thérapeutiques dans les fractures per-trochantériennes ?', '[{"l":"A","t":"Ostéosynthèse à foyer fermé","c":true},{"l":"B","t":"Ostéosynthèse à foyer ouvert","c":true},{"l":"C","t":"Traitement orthopédique","c":true},{"l":"D","t":"Prothèse totale de la hanche","c":false},{"l":"E","t":"Clou gamma","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2056, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'Le traitement des fractures ouvertes de jambe de type III (Cauchoix-Duparc) doit comporter :', '[{"l":"A","t":"Une antibiothérapie ainsi qu''une prévention antitétanique","c":true},{"l":"B","t":"Un parage soigneux des parties molles","c":true},{"l":"C","t":"Une fermeture cutanée primitive","c":false},{"l":"D","t":"Une ostéosynthèse des lésions osseuses par plaque vissée","c":false},{"l":"E","t":"Une ostéosynthèse des lésions osseuses par fixateur externe","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2057, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Concernant la luxation antérieure de l''épaule droite :', '[{"l":"A","t":"Elle survient le plus souvent après une chute sur la main avec rotation externe du bras","c":true},{"l":"B","t":"Elle est plus fréquente chez l''enfant que chez l''adulte","c":false},{"l":"C","t":"La tête humérale se déplace en arrière de la glène","c":false},{"l":"D","t":"Il s''agit de la luxation de l''épaule la plus fréquente","c":true},{"l":"E","t":"Elle est rarement associée à des lésions capsulo-ligamentaires","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2058, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fracture du scaphoïde est :', '[{"l":"A","t":"La fracture la plus fréquente des fractures des os du carpe","c":true},{"l":"B","t":"Le diagnostic est toujours facile au début","c":false},{"l":"C","t":"Parfois découvert au stade de pseudarthrose","c":true},{"l":"D","t":"Le traitement est toujours chirurgical","c":false},{"l":"E","t":"La nécrose du fragment proximal est la complication la plus fréquente de la fracture type 4 : transtubérositaire","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2059, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Parmi les éléments suivants, quels sont ceux qui font partie du segment mobile rachidien ?', '[{"l":"A","t":"Les pédicules","c":false},{"l":"B","t":"Le ligament jaune","c":true},{"l":"C","t":"Le mur postérieur du corps vertébral","c":false},{"l":"D","t":"Le disque","c":true},{"l":"E","t":"Le ligament vertébral commun postérieur","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2060, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les facteurs favorisant la survenue de la goutte, on retrouve :', '[{"l":"A","t":"Consommation excessive d''alcool","c":true},{"l":"B","t":"Insuffisance rénale chronique","c":true},{"l":"C","t":"Sexe féminin avant la ménopause","c":false},{"l":"D","t":"Régime riche en purines","c":true},{"l":"E","t":"La prise de diurétiques thiazidiques","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2061, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'Pour prévenir l''installation des escarres, toutes ces mesures sont justes sauf deux, lesquelles ?', '[{"l":"A","t":"Changement périodique de position","c":false},{"l":"B","t":"Régime hypercalorique hyperprotidique","c":false},{"l":"C","t":"Acidification des urines (vit C) et changement régulier des sondes urinaires","c":true},{"l":"D","t":"Traitement anticoagulant à dose préventive","c":true},{"l":"E","t":"Hygiène corporelle et de la literie","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2062, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'Chez un malade atteint de la Covid-19 installé en décubitus ventral à l''unité de soins intensifs, les localisations les plus vulnérables pour développer des escarres sont :', '[{"l":"A","t":"Occiput","c":false},{"l":"B","t":"Épines iliaques antérosupérieures","c":true},{"l":"C","t":"Front","c":true},{"l":"D","t":"Sacrée et talons","c":false},{"l":"E","t":"Tubérosités tibiales antérieures","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2063, 3, 'MPR', 'MPR', NULL, false, true, 'Dans le cadre de prévention des complications respiratoires d''alitement prolongé, la kinésithérapie respiratoire est basée sur :', '[{"l":"A","t":"Des séances d''aérosol","c":true},{"l":"B","t":"Retournements, Klapping","c":true},{"l":"C","t":"Le drainage bronchique par posture","c":true},{"l":"D","t":"Exercice de la mobilité et d''expansion de la cage thoracique","c":true},{"l":"E","t":"Intubation endotrachéale, parfois trachéotomie","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2064, 12, 'MPR', 'Membre inférieur et locomotion', NULL, false, true, 'Dans la marche (cochez la ou les réponses justes) :', '[{"l":"A","t":"La phase oscillante représente environ 60 % du cycle de la marche","c":false},{"l":"B","t":"Le double appui n''existe pas dans la marche normale","c":false},{"l":"C","t":"La phase d''appui représente environ 60% du cycle de la marche","c":true},{"l":"D","t":"La réception par le talon marque le début de la phase oscillante","c":false},{"l":"E","t":"Le décollage des orteils marque la fin de la phase d''appui et le début de la phase oscillante","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2065, 11, 'MPR', 'Boiterie chez l’enfant', NULL, false, true, 'Parmi les troubles de la marche, laquelle de ces affirmations est vraie ?', '[{"l":"A","t":"Des douleurs à l''appui provoquent une boiterie d''esquive","c":true},{"l":"B","t":"Un déficit du moyen fessier provoque une marche en ciseaux","c":false},{"l":"C","t":"Un déficit du moyen fessier provoque une marche en Trendelenburg","c":true},{"l":"D","t":"Un syndrome cérébelleux provoque une marche ébrieuse","c":true},{"l":"E","t":"Un syndrome parkinsonien provoque une marche piétinante","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2066, 26, 'Chirurgie pédiatrique', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'L''examen clinique de la hanche chez un nouveau-né est :', '[{"l":"A","t":"Obligatoire à la naissance","c":true},{"l":"B","t":"Obligatoire uniquement si le nouveau-né présente des facteurs de risque favorisant une luxation de la hanche","c":false},{"l":"C","t":"Est un examen de dépistage courant","c":true},{"l":"D","t":"Doit être fait par un pédiatre","c":false},{"l":"E","t":"Toute asymétrie est suspecte et doit approfondir les explorations","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2067, 17, 'Chirurgie pédiatrique', 'Chirurgie pédiatrique', NULL, false, true, 'Dans l''examen de dépistage d''une LCH, le signe de Galeazzi est :', '[{"l":"A","t":"Une asymétrie des plis inguinaux","c":false},{"l":"B","t":"Une asymétrie des plis fessiers","c":false},{"l":"C","t":"Une asymétrie des plis poplités","c":false},{"l":"D","t":"Un raccourcissement de la cuisse","c":true},{"l":"E","t":"Une limitation de l''abduction","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2068, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Concernant les Infections ostéo-articulaires :', '[{"l":"A","t":"Elles touchent exclusivement l''os","c":false},{"l":"B","t":"Elles regroupent l''ostéomyélite, l''arthrite septique et la spondylodiscite","c":true},{"l":"C","t":"Elles sont toujours d''origine traumatique","c":false},{"l":"D","t":"Elles peuvent être aigues ou chroniques","c":true},{"l":"E","t":"Elles ne concernent que l''adulte","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2069, 21, 'Chirurgie pédiatrique', 'Arthrite septique', NULL, false, true, 'À propos de l''arthrite septique :', '[{"l":"A","t":"C''est une urgence médico-chirurgicale","c":true},{"l":"B","t":"Elle peut entraîner une destruction articulaire rapide","c":true},{"l":"C","t":"La ponction articulaire est un examen clé","c":true},{"l":"D","t":"Elle est toujours polyarticulaire","c":false},{"l":"E","t":"Le genou est une articulation fréquemment touchée","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2070, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Concernant le traitement des Infections ostéo-articulaires :', '[{"l":"A","t":"L''antibiothérapie probabiliste est débutée après les prélèvements","c":true},{"l":"B","t":"La durée du traitement est courte (5-7 jours)","c":false},{"l":"C","t":"Le traitement peut être adapté après antibiogramme","c":true},{"l":"D","t":"Un drainage chirurgical peut être nécessaire","c":true},{"l":"E","t":"Le repos et l''immobilisation sont recommandés au début","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2071, 14, 'Chirurgie pédiatrique', 'Chirurgie pédiatrique', NULL, false, true, 'Concernant le métatarsus adductus, quelles propositions sont exactes ?', '[{"l":"A","t":"Il correspond à une déviation médiale de l''avant-pied, avec arrière-pied normal","c":true},{"l":"B","t":"Il est lié le plus souvent à une contrainte intra-utérine","c":true},{"l":"C","t":"Il est fréquemment associé à un pied bot varus équin","c":false},{"l":"D","t":"La majorité des formes sont souples et régressent spontanément","c":true},{"l":"E","t":"Le traitement repose sur un traitement chirurgical d''emblée","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2072, 14, 'Chirurgie pédiatrique', 'Chirurgie pédiatrique', NULL, false, true, 'Concernant la prise en charge des malformations du pied chez l''enfant, quelles propositions sont exactes ?', '[{"l":"A","t":"Le traitement orthopédique est souvent privilégié en première intention","c":true},{"l":"B","t":"Le pied bot varus équin idiopathique nécessite une prise en charge précoce dès les premières semaines de vie","c":true},{"l":"C","t":"Les attelles et plâtres sont inutiles après l''âge de la marche","c":false},{"l":"D","t":"La chirurgie est toujours indiquée en cas d''échec partiel du traitement orthopédique","c":false},{"l":"E","t":"La compliance familiale est un facteur majeur du succès thérapeutique","c":true}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2073, 23, 'Chirurgie pédiatrique', 'Chirurgie pédiatrique', NULL, false, true, 'Quel est le principal examen pour dépister la scoliose ?', '[{"l":"A","t":"L''IRM","c":false},{"l":"B","t":"La radiographie de la colonne vertébrale","c":true},{"l":"C","t":"Test et mesure de l''angle de Cobb","c":false},{"l":"D","t":"L''examen de la mobilité articulaire","c":false},{"l":"E","t":"L''échographie","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2074, 23, 'Chirurgie pédiatrique', 'Chirurgie pédiatrique', NULL, false, true, 'Lors de l''examen clinique d''une scoliose, lequel (lesquels) des points suivants est(sont) essentiel(s) pour évaluer la gravité de la déformation :', '[{"l":"A","t":"L''évaluation de l''angle de Cobb par radiographie","c":true},{"l":"B","t":"L''observation de la symétrie des épaules et des hanches","c":true},{"l":"C","t":"La mesure de la flexion du genou","c":false},{"l":"D","t":"L''évaluation de la mobilité thoracique","c":false},{"l":"E","t":"La vérification de la posture assise","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2025-2026"]'::jsonb),
(2075, 42, 'Traumatologie', 'Jambe et cheville', NULL, false, true, 'Devant une fracture ouverte de la jambe chez un patient en bon état général, la première chose à faire après l''examen clinique est :', '[{"l":"A","t":"Admettre le patient en urgence au bloc opératoire pour un traitement chirurgical","c":false},{"l":"B","t":"Demander un examen radiologique standard","c":false},{"l":"C","t":"Nettoyer et suturer la plaie","c":false},{"l":"D","t":"Nettoyer la plaie et la couvrir par un pansement stérile, administrer un traitement antibiotique et antalgique","c":true},{"l":"E","t":"Immobiliser par une attelle cruro-pédieuse","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2022-2023"]'::jsonb),
(2076, 31, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'La déformation clinique en flexion de la hanche, adduction et rotation externe, évoque d''emblée :', '[{"l":"A","t":"Une fracture de la diaphyse fémorale","c":false},{"l":"B","t":"Une fracture trochantérienne","c":false},{"l":"C","t":"Une luxation de hanche dans sa variété antérieure","c":true},{"l":"D","t":"Une fracture du col du fémur","c":false},{"l":"E","t":"Une luxation de la hanche dans sa variété postérieure","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2022-2023"]'::jsonb),
(2077, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'Les fractures pertrochantériennes de l''extrémité supérieure du fémur sont plus exposées dans leur évolution que les fractures transcervicales, au risque de :', '[{"l":"A","t":"Pseudarthrose","c":false},{"l":"B","t":"Cal vicieux","c":true},{"l":"C","t":"Complications de décubitus","c":false},{"l":"D","t":"Nécrose ischémique de la tête fémorale","c":false},{"l":"E","t":"Démontage du matériel d''ostéosynthèse","c":false}]'::jsonb, NULL, '["EMD Mostaganem 2022-2023"]'::jsonb),
(2078, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Laquelle n’entraîne pas de syndrome épaule-main', '[{"l":"A","t":"Chute sur l’épaule","c":false},{"l":"B","t":"Prise régulière de Gardénal","c":false},{"l":"C","t":"Ablation neurochirurgicale d’un méningiome intracrânien","c":false},{"l":"D","t":"Exploration thyroïdienne par iode radioactif","c":false},{"l":"E","t":"Prise quotidienne de somnifères (Mogadon)","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2079, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Signes classiquement observables à la phase tardive d’une algodys- trophie de la main', '[{"l":"A","t":"Limitation de la mobilité","c":true},{"l":"B","t":"Rétraction des fléchisseurs des doigts","c":true},{"l":"C","t":"Amyotrophie","c":true},{"l":"D","t":"Perte de la souplesse de la peau","c":true},{"l":"E","t":"Calcification sous-cutanée","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2080, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Quels médicaments peuvent être en cause d’une algodystrophie', '[{"l":"A","t":"Isoniazides","c":true},{"l":"B","t":"Phénobarbital","c":true},{"l":"C","t":"Piroxicam","c":false},{"l":"D","t":"Coumadine","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2081, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'L’algodystrophie de la main et du poignet au premier moi de son évolution se traduit classiquement par :', '[{"l":"A","t":"Gonflement & hyperthermie locale","c":true},{"l":"B","t":"Sensibilité très douloureuse à la pression des épiphyses et du carpe","c":true},{"l":"C","t":"Une radiotransparence osseuse homogène","c":false},{"l":"D","t":"Pincement des interlignes articulaires du carpe","c":false},{"l":"E","t":"Radiotransparence osseuse hétérogène pommelé","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2082, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'L’algodystrophie de hanche', '[{"l":"A","t":"Guérit habituellement sans séquelle","c":true},{"l":"B","t":"Surtout observé chez la femme au 3e trimestre de grossesse","c":true},{"l":"C","t":"Il existe un risque de fracture du col fémoral","c":true},{"l":"D","t":"Entraîne un pincement tardif de l’interligne articulaire","c":false},{"l":"E","t":"Appelée aussi ostéoporose localisée de la hanche","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2083, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'A la phase précoce de l’algodystrophie du poignet les techniques d’imagerie montrent :', '[{"l":"A","t":"Hyperfixation scintigraphique","c":true},{"l":"B","t":"Un pincement de l’interligne radio-carpien","c":false},{"l":"C","t":"Un épaississement des parties molles","c":false},{"l":"D","t":"Des érosions osseuses juxta-articulaires","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2084, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Une épaule douloureuse fébrile peut correspondre à toutes ces causes sauf unes :', '[{"l":"A","t":"Une arthrite infectieuse","c":false},{"l":"B","t":"Une crise de chondrocalcinose","c":false},{"l":"C","t":"Une algodystrophie","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2085, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'L’algodystrophie post-traumatique se rencontre', '[{"l":"A","t":"Le plus souvent après une fracture ouverte","c":false},{"l":"B","t":"Même après traumatisme minime","c":true},{"l":"C","t":"Fréquemment chez les sujets anxieux","c":true},{"l":"D","t":"Fréquemment après fracture de Pouteau-Colles","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2086, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Signes qui font craindre une algodystrophie de la main', '[{"l":"A","t":"Douleur","c":true},{"l":"B","t":"Œdème","c":true},{"l":"C","t":"Perte de la sensibilité superficielle","c":false},{"l":"D","t":"Abolition des pouls","c":false},{"l":"E","t":"Hypersudation","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2087, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Les éléments qui vont contre une algodystrophie sont :', '[{"l":"A","t":"VS élevée","c":true},{"l":"B","t":"Radiographies normales","c":false},{"l":"C","t":"Mobilisation douloureuse de l’articulation concernée","c":false},{"l":"D","t":"Température élevée","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2088, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Quelles sont les mesures thérapeutiques préconisées en cas l’algodystrophie de pied récente', '[{"l":"A","t":"Calcitonine","c":true},{"l":"B","t":"Mise en décharge du côté atteint","c":true},{"l":"C","t":"Des massages de drainage veineux et lymphatique","c":true},{"l":"D","t":"Kinébalnéothérapie des articulations touchées","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2089, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, '… l’élément qui va contre l’algodystrophie est', '[{"l":"A","t":"VS à 52 mm/1e heure","c":true},{"l":"B","t":"Radiographie normale","c":false},{"l":"C","t":"Mobilisation de l’articulation atteinte douloureuse","c":false},{"l":"D","t":"Température à 37,2°C","c":false},{"l":"E","t":"Aspect rouge et oedématié localement","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2090, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Les mesures thérapeutiques proposées en cas d’algodystrophie ré- cente sont :', '[{"l":"A","t":"Un traitement par la calcitonine","c":true},{"l":"B","t":"Une mise en décharge du côté atteint","c":true},{"l":"C","t":"Une kinébalnéothérapie des articulations touchées","c":true},{"l":"D","t":"Des massages de drainage veineux et lymphatique","c":true},{"l":"E","t":"L’immobilisation dans une attelle plâtrée","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2091, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Signes radiologiques de coxarthrose (RF)', '[{"l":"A","t":"Pincement de l’interligne coxo-fémorale","c":false},{"l":"B","t":"Présence d’ostéophytes","c":false},{"l":"C","t":"Présence de Géodes","c":false},{"l":"D","t":"Existence d’une déminéralisation sous-chondrale","c":true},{"l":"E","t":"Excentration de la tête fémorale","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2092, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Un homme de 50 ans a une douleur isolée mécanique du genou droit. L’examen clinique du genou est normal de même que les radiographies du genou. Quel est l’examen complémentaire à proposer en premier', '[{"l":"A","t":"Scintigraphie osseuse","c":false},{"l":"B","t":"Radiographie du bassin","c":true},{"l":"C","t":"Tomodensitométrie du genou","c":false},{"l":"D","t":"Ponction articulaire","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2093, 31, 'Rhumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'Une coxarthrose débutante compliquant une dysplasie de hanche peut comporter :', '[{"l":"A","t":"une exagération de l’obliquité du toit du cotyle","c":true},{"l":"B","t":"une insuffisance de couverture externe de la tête fémorale","c":true},{"l":"C","t":"une coxa valga","c":true},{"l":"D","t":"une antéversion exagérée du col du fémur","c":true},{"l":"E","t":"une conservation du cintre cervico-obturateur","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2094, 26, 'Rhumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Les maladies qui peuvent donner la coxarthrose sont', '[{"l":"A","t":"Coxa plana (maladie de Legg Perthes Calve)","c":true},{"l":"B","t":"Coxa retrorsa","c":true},{"l":"C","t":"Fracture du cotyle","c":true},{"l":"D","t":"Algodystrophie de hanche","c":false},{"l":"E","t":"Ostéonécrose de la tête fémorale","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2095, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Les mesures proposées à un malade coxarthrosique', '[{"l":"A","t":"Le port d’une canne","c":true},{"l":"B","t":"La suppression des longues marches","c":true},{"l":"C","t":"Le cyclisme sur terrain plat","c":true},{"l":"D","t":"La réduction de la surcharge pondérale","c":true},{"l":"E","t":"Les manipulations de la hanche","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2096, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, false, 'Une femme se plaint de douleurs osseuses diffuses. Le bilan biolo- gique révèle : - Calcémie = 2,00 micromoles (80 mg/l) - Phosphorémie = 0,60 micromoles (18 mg/l) - Phosphatases alcalines = 5 fois le taux normal. Le diagnostic probable est :', '[{"l":"A","t":"Ostéoporose","c":false},{"l":"B","t":"Ostéomalacie","c":false},{"l":"C","t":"Maladie osseuse de Paget","c":false},{"l":"D","t":"Cancer secondaire des os","c":false},{"l":"E","t":"Myélome multiple des os","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2097, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, false, 'Quel est (ou quels sont) le(s) signe(s) radiologique(s) qu’on rencontre dans l’ostéoporose ?', '[{"l":"A","t":"Lyse d’une épineuse","c":false},{"l":"B","t":"Lacunes à l’emporte pièce","c":false},{"l":"C","t":"Tassements vertébraux","c":false},{"l":"D","t":"Déformation en cupule puis en galette des plateaux vertébraux","c":false},{"l":"E","t":"Pincement discal","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2098, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, false, 'Devant un tassement vertébral, quels sont les aspects scintigra- phiques qui doivent faire remettre en cause un diagnostic d’ostéoporose', '[{"l":"A","t":"Hyperfixation localisée à un tassement vertébral récent","c":false},{"l":"B","t":"Hyperfixations multiples extra rachidiennes","c":false},{"l":"C","t":"Isofixation","c":false},{"l":"D","t":"Hypofixation localisée","c":false},{"l":"E","t":"Scintigraphie normale","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2099, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'Parmi les facteurs suivants, lequel ou lesquels peut-on incriminer dans l''apparition de cette ostéoporose', '[{"l":"A","t":"L''obésité","c":false},{"l":"B","t":"L''annexectomie","c":true},{"l":"C","t":"L''hystérectomie","c":false},{"l":"D","t":"L''hypothyroïdie","c":true},{"l":"E","t":"L''intoxication tabagique","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2100, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, false, 'Quel est ou quels sont le(s) signe(s) radiologique(s) qu''on rencontre dans l''ostéoporose ?', '[{"l":"A","t":"Tassements vertébraux","c":false},{"l":"B","t":"Lyse d''une épineuse","c":false},{"l":"C","t":"Raréfaction osseuse diffuse","c":false},{"l":"D","t":"Déformation en cupule des plateaux vertébraux","c":false},{"l":"E","t":"Pincement discal","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2101, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'Dans l''ostéomalacie pure, il existe habituellement une :', '[{"l":"A","t":"Hypocalcémie","c":true},{"l":"B","t":"Hypophosphatémie","c":true},{"l":"C","t":"Augmentation des phosphatases alcalines","c":true},{"l":"D","t":"Hypercalciurie","c":false},{"l":"E","t":"Diminution de la sécrétion de parathormone","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2102, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'L’ostéomalacie :', '[{"l":"A","t":"Correspond à la même définition histologique que celle de l’ostéoporose","c":false},{"l":"B","t":"Est souvent liée à une carence en vitamine E","c":false},{"l":"C","t":"Peut être responsable de fracture du col fémoral","c":true},{"l":"D","t":"Induit des fissures osseuses d’aspect radiologique caractéristique","c":true},{"l":"E","t":"Peut être révélée par une crise de tétanie","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2103, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'Quel est le paramètre qui reflète l’activité ostéoblastique', '[{"l":"A","t":"Calcémie","c":false},{"l":"B","t":"Phosphorémie","c":false},{"l":"C","t":"Calciurie","c":false},{"l":"D","t":"Hydroxyprolinurie","c":false},{"l":"E","t":"Phosphatasémie alcaline","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2104, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, false, 'Dans l’ostéomalacie carentielle du sujet âgé, on observe :', '[{"l":"A","t":"Une hypocalcémie souvent modérée","c":false},{"l":"B","t":"Une hyperphosphorémie","c":false},{"l":"C","t":"L’absence d’amélioration sous calcium","c":false},{"l":"D","t":"La possibilité d’un traitement préventif par petites doses de vi- tamine D Ad","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2105, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'L’ostéoporose peut être favorisée par', '[{"l":"A","t":"L’alcoolisme","c":true},{"l":"B","t":"Une insolation insuffisante","c":false},{"l":"C","t":"L’ovariectomie chez la femme non ménopausée","c":true},{"l":"D","t":"L’héparine","c":true},{"l":"E","t":"Un traitement prolongé par les AVK","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2106, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Le diagnostic peut être affirmer par un simple cliché radiographique de l’articulation douloureuse lors d’une crise fluxionnaire aiguë :', '[{"l":"A","t":"Chondrocalcinose articulaire","c":true},{"l":"B","t":"Crise aiguë de goutte","c":false},{"l":"C","t":"Rhumatisme à hydroxyapatite","c":true},{"l":"D","t":"Arthrite réactionnelle","c":false},{"l":"E","t":"Rhumatisme articulaire aigu","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2107, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'La goutte peut résulter sur le plan physiopathologique de', '[{"l":"A","t":"Déficit en urate-oxydase Page 49/52","c":false},{"l":"B","t":"Synthèse excessive d’acide urique","c":true},{"l":"C","t":"Catabolisme excessif des acides nucléiques","c":true},{"l":"D","t":"Déficit en xanthine-oxydase","c":false},{"l":"E","t":"Défaut d’élimination rénale de l’acide urique","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2108, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Un goutteux fait une colique néphrétique avec émission de calculs d’urates. Il a une hyperuricémie à 490 µmol/L. la première prescription est :', '[{"l":"A","t":"Uricosurique","c":false},{"l":"B","t":"Uricofreinateur","c":false},{"l":"C","t":"Régime adapté hypopurinique","c":false},{"l":"D","t":"Diurèse abondante alcaline","c":true},{"l":"E","t":"Colchicine","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2109, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Un homme goutteux porteur de nombreux tophi, présentant biologi- quement une hyperuricémie, a une lithiase urinaire. Outre la cure de diurèse et d’alcalinisation des urines. On prescrit de l’Allopurinol :', '[{"l":"A","t":"Il n’y a pas lieu de prescrire la colchicine","c":false},{"l":"B","t":"De la colchicine doit être également prescrite à la dose de 3 mg/j en traitement prolongé","c":false},{"l":"C","t":"De la colchicine doit être également prescrite à la dose de 1 mg/j pendant 1 mois","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
(2110, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Quelles sont les propositions exactes concernant la polyarthrite rhu- matoïde', '[{"l":"A","t":"L’atteinte des interphalangiennes distales des mains est possible","c":false},{"l":"B","t":"Le gonflement en fuseau de plusieurs doigts est un mode de début","c":true},{"l":"C","t":"L’atteinte des métacarpo-phalangiennes est fréquente et souvent précoce","c":true},{"l":"D","t":"Le facteur rhumatoïde est l’auto-Ac le plus spécifique","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
