(2113, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Polyarthrite rhumatoïde (RJ)', '[{"l":"A","t":"L’atteinte des interphalangiennes distales est habituelles","c":false},{"l":"B","t":"Le gonflement en fuseau de plusieurs doigts est un mode de début","c":true},{"l":"C","t":"L’atteinte des métatarsophalangiennes est fréquente et souvent précoce","c":true},{"l":"D","t":"Les articulations atteintes sont chaudes à la palpation","c":true}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
