(2140, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'Les stries de Looser-Milkman', '[{"l":"A","t":"Sont des fractures incomplètes","c":true},{"l":"B","t":"Sont trouvées sur les côtes, le pelvis, l’omoplate et les os long","c":true},{"l":"C","t":"Sont généralement parallèles au grand axe de l’os","c":false},{"l":"D","t":"Peuvent être responsables de douleurs","c":true},{"l":"E","t":"Ne donnent pas d’hyperfixation en scintigraphie","c":false}]'::jsonb, NULL, '["Amis-med Rhumatologie (QCM)"]'::jsonb),
